                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < 8:
                        # Mark all edges in this cycle as bad
                        # Trace back the cycle
